.getString(columnIndex));\n    }\n\n    private Map<String, Object> parse(String value) throws SQLException {\n        if (value == null) {\n            return null;\n        }\n\n        try {\n            return objectMapper.readValue(value, MAP_TYPE);\n        } catch (Exception ex) {\n            throw new SQLException(\"Failed to parse JSONB value\", ex);\n        }\n    }\n}\n"
